let base = {};
try {
  base = $('Build AI Audit Score Prompt').item.json || {};
} catch (error) {
  base = {};
}

function parseAiOutput(input) {
  if (!input) return {};

  if (typeof input === 'object') {
    if (input.output && typeof input.output === 'object') return input.output;
    if (input.output && typeof input.output === 'string') return parseAiOutput(input.output);
    if (input.response && typeof input.response === 'object') return parseAiOutput(input.response.output || input.response.text || input.response);
    return input;
  }

  if (typeof input === 'string') {
    let text = input.trim();

    text = text.replace(/^```json/i, '');
    text = text.replace(/^```/i, '');
    text = text.replace(/```$/i, '');
    text = text.trim();

    try {
      return JSON.parse(text);
    } catch (error) {
      const match = text.match(/\{[\s\S]*\}/);
      if (match) {
        try {
          return JSON.parse(match[0]);
        } catch (error2) {}
      }
      return {};
    }
  }

  return {};
}

function asText(value) {
  if (Array.isArray(value)) return value.join(' | ');
  if (value === undefined || value === null) return '';
  return String(value);
}

function firstText(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value);
    }
  }
  return '';
}

let raw =
  $json.output ||
  $json.response?.output ||
  $json.text ||
  $json;

const parsed = parseAiOutput(raw);

const score = Math.max(0, Math.min(100, Number(parsed.audit_score || 0)));

let category = parsed.lead_category;
if (!['Hot', 'Warm', 'Cold'].includes(category)) {
  category = score >= 75 ? 'Hot' : score >= 45 ? 'Warm' : 'Cold';
}

let nextAction = parsed.next_action || '';
if (!nextAction) {
  if (category === 'Hot') nextAction = 'Book discovery call within 24 hours';
  else if (category === 'Warm') nextAction = 'Send manual review summary and ask qualification questions';
  else nextAction = 'Add to nurture list';
}

let callStatus = 'Not Booked';
let proposalStatus = 'Not Started';

if (category === 'Hot') {
  callStatus = 'To Book';
  proposalStatus = 'Prepare Draft';
} else if (category === 'Warm') {
  callStatus = 'Manual Review Needed';
  proposalStatus = 'Wait for Qualification';
} else {
  callStatus = 'Not Required';
  proposalStatus = 'Not Required';
}

const fullName = firstText(base.full_name, base['Full name']);
const recommendedWorkflow = firstText(parsed.recommended_workflow, parsed.recommended_offer, 'Automation opportunity identified');
const leadReplyBody = firstText(parsed.lead_reply_email_body, 'Our team will contact you soon with the next step.');

const leadConfirmationEmailBody =
  `Hi ${fullName},<br><br>` +
  `Thank you for submitting the <b>AKcelerateHQ Automation Audit</b> form.<br><br>` +
  `We reviewed your answers and identified this possible automation opportunity:<br><br>` +
  `<b>${recommendedWorkflow}</b><br><br>` +
  `${leadReplyBody}<br><br>` +
  `Regards,<br>` +
  `AKcelerateHQ<br>` +
  `Automate the busywork. Accelerate growth.`;

return {
  json: {
    ...base,

    // Important:
    // AI scoring is NOT the final stage.
    // Keep processed false so Smart Routing can pick this row next.
    processed: true,
    status: 'Scored',

    audit_score: score,
    lead_category: category,
    priority_reason: parsed.priority_reason || '',
    recommended_offer: parsed.recommended_offer || '',
    recommended_workflow: parsed.recommended_workflow || '',
    next_action: nextAction,
    business_summary: parsed.business_summary || '',
    pain_summary: parsed.pain_summary || '',
    suggested_solution: parsed.suggested_solution || '',
    estimated_hours_lost_weekly: parsed.estimated_hours_lost_weekly || '',
    monthly_value_estimate_usd: parsed.monthly_value_estimate_usd || '',
    automation_fit_score: parsed.automation_fit_score || '',
    pain_severity_score: parsed.pain_severity_score || '',
    urgency_score: parsed.urgency_score || '',
    budget_score: parsed.budget_score || '',
    authority_score: parsed.authority_score || '',
    data_readiness_score: parsed.data_readiness_score || '',
    revenue_fit_score: parsed.revenue_fit_score || '',
    discovery_questions: asText(parsed.discovery_questions),
    risks_or_blockers: asText(parsed.risks_or_blockers),
    tools_to_integrate: asText(parsed.tools_to_integrate),
    recommended_action: nextAction,
    assigned_owner: 'Kalpesh',
    call_status: callStatus,
    proposal_status: proposalStatus,
    n8n_sent: true,
    n8n_response: 'AI audit scoring completed',
    notes: parsed.internal_notes || '',
    lead_reply_email_subject: parsed.lead_reply_email_subject || 'Your AKcelerateHQ automation audit has been received',
    lead_reply_email_body: parsed.lead_reply_email_body || '',
    lead_confirmation_email_body: leadConfirmationEmailBody,
    whatsapp_message: parsed.whatsapp_message || '',
    updated_at: new Date().toISOString()
  }
};

