function normalizePhone(input) {
  if (!input) return '';
  let v = String(input).replace(/[^0-9+]/g, '');
  if (v.startsWith('+')) return v;
  if (v.length === 10) return '+91' + v;
  if (v.startsWith('91') && v.length === 12) return '+' + v;
  return v;
}

function containsAny(text, keywords) {
  text = String(text || '').toLowerCase();
  return keywords.some(k => text.includes(k.toLowerCase()));
}

function getTomorrow11AMIST() {
  const now = new Date();
  const istNow = new Date(now.getTime() + 5.5 * 60 * 60 * 1000);
  const year = istNow.getUTCFullYear();
  const month = istNow.getUTCMonth();
  const day = istNow.getUTCDate() + 1;
  const startUtc = new Date(Date.UTC(year, month, day, 5, 30, 0));
  const endUtc = new Date(startUtc.getTime() + 30 * 60 * 1000);
  return {
    start: startUtc.toISOString(),
    end: endUtc.toISOString()
  };
}

const row = $json;

const score = Number(row.audit_score || 0);
const category = String(row.lead_category || '').trim();

const budget = String(row.Budget || row.budget || '').toLowerCase();
const timeline = String(row.Timeline || row.timeline || '').toLowerCase();
const authority = String(row['Decision authority'] || row.decision_authority || '').toLowerCase();
const pain = String(row['Where is the biggest pain? (pick all that apply)'] || row.biggest_pain || '').toLowerCase();
const workflowWanted = String(row["Which workflows would you like AI to handle?\n\n(Be specific — e.g., 'classify inbound emails, draft replies, sync to CRM')"] || row.workflows_ai_handle || '').toLowerCase();
const outcomes = String(row['Desired outcomes'] || row.desired_outcomes || '').toLowerCase();
const tools = String(row['Tools you currently use'] || row.tools_currently_use || '').toLowerCase();
const revenue = String(row['Monthly revenue'] || row.monthly_revenue || '').toLowerCase();
const hoursLost = String(row['Estimated hours lost per week to manual work'] || row.hours_lost_per_week || '').toLowerCase();
const industry = String(row.Industry || row.industry || '').toLowerCase();

const fullName = row['Full name'] || row.full_name || '';
const companyName = row['Company name'] || row.company_name || '';
const workEmail = row['Work email'] || row.work_email || row['Email address'] || '';
const contactNo = normalizePhone(row['Contact No'] || row.contact_no || '');

let workflow_type = 'general_automation';

if (containsAny(pain + workflowWanted, ['lead qualification', 'lead', 'crm', 'sales', 'conversion'])) {
  workflow_type = 'lead_crm_automation';
} else if (containsAny(pain + workflowWanted, ['report', 'dashboard', 'forecasting', 'planning', 'analytics', 'power bi', 'powerbi'])) {
  workflow_type = 'reporting_dashboard';
} else if (containsAny(pain + workflowWanted, ['customer support', 'support', 'reply', 'inbound emails', 'draft replies'])) {
  workflow_type = 'support_email_ai';
} else if (containsAny(pain + workflowWanted, ['document', 'invoice', 'sop', 'approval', 'processing'])) {
  workflow_type = 'document_processing';
} else if (containsAny(pain + workflowWanted, ['onboarding', 'handoff', 'operations', 'approval workflows'])) {
  workflow_type = 'operations_workflow';
} else if (containsAny(pain + workflowWanted, ['inventory', 'supply chain', 'quality', 'compliance'])) {
  workflow_type = 'msme_operations_control';
} else if (containsAny(tools + industry, ['shopify', 'stripe', 'ecommerce', 'e-commerce'])) {
  workflow_type = 'ecommerce_automation';
}

let recommendedOffer = row.recommended_offer || 'Automation Audit + Starter Workflow Demo';

if (workflow_type === 'lead_crm_automation') {
  recommendedOffer = 'Lead Qualification + CRM Follow-up System';
} else if (workflow_type === 'reporting_dashboard') {
  recommendedOffer = 'Reporting Dashboard + Owner Summary Automation';
} else if (workflow_type === 'support_email_ai') {
  recommendedOffer = 'AI Customer Support Triage + Reply Drafting';
} else if (workflow_type === 'document_processing') {
  recommendedOffer = 'Document Processing + Approval Workflow';
} else if (workflow_type === 'operations_workflow') {
  recommendedOffer = 'MSME Operations Workflow Automation';
} else if (workflow_type === 'msme_operations_control') {
  recommendedOffer = 'AI MSME Operations Control System';
} else if (workflow_type === 'ecommerce_automation') {
  recommendedOffer = 'E-commerce Order, CRM & Reporting Automation';
}

const strongBudget =
  containsAny(budget, ['$1,000', '$2,000', '$6,000', '6000', 'prefer to discuss', '₹25,000', '₹50,000', '₹1,00,000', '25000', '50000', '100000', '1 lakh']) ||
  containsAny(revenue, ['$25,000', '$100,000', '100,000']);

const weakBudget =
  containsAny(budget, ['less than $300', 'less than ₹10,000', 'less than ₹15000', 'not sure yet', 'no budget']) ||
  containsAny(revenue, ['pre-revenue']);

const urgentTimeline = containsAny(timeline, ['asap', '< 21 days', 'immediately', 'this month', 'within 2 weeks']);
const flexibleTimeline = containsAny(timeline, ['1-3 months', 'flexible']);
const justExploring = containsAny(timeline, ['just exploring']);

const hasAuthority = containsAny(authority, ['yes, i decide', 'buying committee']);
const lowAuthority = containsAny(authority, ['researching', 'influence']);

const highPain =
  containsAny(hoursLost, ['15–40', '40–100', '100+']) ||
  containsAny(pain, [
    'manual data entry',
    'slow customer support',
    'lead qualification overhead',
    'document processing',
    'repetitive reporting'
  ]);

let route = 'manual_review';
let finalCategory = category || 'Warm';
let finalScore = score;
let callStatus = 'Not Booked';
let proposalStatus = 'Not Started';
let status = 'Manual Review';
let nextAction = row.next_action || '';
let routeReason = 'Needs human review before next step.';

if (
  finalScore >= 75 ||
  finalCategory === 'Hot' ||
  (strongBudget && urgentTimeline && hasAuthority && highPain)
) {
  route = 'discovery_call';
  finalCategory = 'Hot';
  status = 'Discovery Scheduled';
  callStatus = 'Discovery Scheduled';
  proposalStatus = 'Prepare Draft';
  routeReason = 'High-intent lead with strong pain, urgency, authority, or budget.';
  nextAction = 'Book discovery call and prepare ROI-based automation recommendation.';
} else if (
  finalScore >= 45 ||
  finalCategory === 'Warm' ||
  (flexibleTimeline && highPain) ||
  (strongBudget && lowAuthority)
) {
  route = 'manual_review';
  finalCategory = 'Warm';
  status = 'Manual Review';
  callStatus = 'Manual Review Needed';
  proposalStatus = 'Wait for Qualification';
  routeReason = 'Potential fit, but needs more clarity on scope, budget, authority, or timeline.';
  nextAction = 'Send qualification questions and review manually.';
} else {
  route = 'nurture';
  finalCategory = 'Cold';
  status = 'Nurture';
  callStatus = 'Not Required';
  proposalStatus = 'Not Required';
  routeReason = 'Low urgency, weak budget, unclear ROI, or early exploration stage.';
  nextAction = 'Send helpful nurture email and follow up later.';
}

let email_subject = '';
let email_body = '';

if (route === 'discovery_call') {
  email_subject = `AKcelerateHQ Discovery Call - ${companyName}`;
  email_body = `Hi ${fullName},<br><br>Thanks for submitting your AKcelerateHQ Automation Audit request.<br><br>Based on your answers, your business looks like a strong fit for automation, especially around:<br><b>${recommendedOffer}</b><br><br>We have scheduled a discovery call to understand your workflow, current tools, and ROI opportunity.<br><br><b>Call Time:</b> {{DISCOVERY_TIME}}<br><b>Google Meet:</b> {{GOOGLE_MEET_LINK}}<br><br>Please keep these ready before the call:<br>1. Your current workflow/process<br>2. Tools you currently use<br>3. Where your team loses the most time<br>4. Any sample Sheet, SOP, report, or CRM export if available<br><br>Regards,<br>AKcelerateHQ`;
}

if (route === 'manual_review') {
  email_subject = `A few questions about your automation audit - ${companyName}`;
  email_body = `Hi ${fullName},<br><br>Thanks for submitting your AKcelerateHQ Automation Audit request.<br><br>Your use case has automation potential, but we need a little more clarity before recommending the right system.<br><br>From your form, the best starting point looks like:<br><b>${recommendedOffer}</b><br><br>Please reply with answers to these 3 questions:<br>1. Which task is repeated daily or weekly by your team?<br>2. Which tool contains the main data today — Google Sheets, CRM, Excel, WhatsApp, email, or something else?<br>3. If this workflow is automated, what result matters most — time saved, faster response, fewer errors, or more sales?<br><br>After that, we can suggest the most practical next step.<br><br>Regards,<br>AKcelerateHQ`;
}

if (route === 'nurture') {
  email_subject = `Your AKcelerateHQ Automation Audit request`;
  email_body = `Hi ${fullName},<br><br>Thanks for submitting your AKcelerateHQ Automation Audit request.<br><br>At this stage, it looks like you may still be exploring automation options. That is completely fine.<br><br>A good first step is to identify one simple workflow that is repetitive, measurable, and easy to test — for example:<br>- lead follow-up<br>- reporting<br>- customer reply drafting<br>- data entry<br>- document processing<br><br>When you are ready, we can help you choose one workflow and build a small automation demo before scaling further.<br><br>Regards,<br>AKcelerateHQ`;
}

const discovery = getTomorrow11AMIST();

return {
  json: {
    ...row,
    full_name: fullName,
    company_name: companyName,
    work_email: workEmail,
    contact_no: contactNo,
    route,
    workflow_type,
    audit_score: finalScore,
    lead_category: finalCategory,
    recommended_offer: recommendedOffer,
    priority_reason: row.priority_reason || routeReason,
    route_reason: routeReason,
    next_action: nextAction,
    email_subject,
    email_body,
    discovery_start: discovery.start,
    discovery_end: discovery.end,
    discovery_time: discovery.start,
    status,
    processed: true,
    assigned_owner: row.assigned_owner || 'Kalpesh',
    call_status: callStatus,
    proposal_status: proposalStatus,
    n8n_sent: true,
    n8n_response: `Routed as ${route} using score + form selections`,
    notes: `${row.notes || ''} | Route: ${route} | Workflow type: ${workflow_type} | Reason: ${routeReason}`,
    updated_at: new Date().toISOString()
  }
};

const output = [];

for (const item of $input.all()) {
  const row = item.json;

  const status = String(row.status || '').toLowerCase().trim();
  const category = String(row.lead_category || '').trim();
  const score = Number(row.audit_score || 0);

  // Final routed statuses only.
  // Keep Scored / AI Scored OUT of this list because those still need routing.
  const alreadyRoutedStatuses = [
    'discovery scheduled',
    'manual review',
    'nurture',
    'proposal sent',
    'not fit',
    'closed',
    'won',
    'lost'
  ];

  if (alreadyRoutedStatuses.includes(status)) continue;

  const isScored =
    status === 'scored' ||
    status === 'ai scored' ||
    score > 0 ||
    ['Hot', 'Warm', 'Cold'].includes(category);

  if (isScored) {
    output.push({ json: row });
  }
}

return output;

