let base = {};

try {
  base = $('Audit Lead Loop').item.json;
} catch (error) {
  base = $json;
}

const auditContext = `
AKcelerateHQ helps businesses automate repetitive work using:
- n8n workflow automation
- AI agents
- CRM integrations
- Google Workspace / Microsoft 365 automations
- dashboards and reporting
- WhatsApp/email follow-up systems
- document processing and approval workflows
- smart internal systems
`;

const prompt = `
You are AKcelerateHQ's Automation Audit Lead Scoring Agent.

${auditContext}

Lead details:
Name: ${base.full_name}
Work email: ${base.work_email}
Contact No: ${base.contact_no}
Role in Business: ${base.role_in_business}
Company name: ${base.company_name}
Website: ${base.website}
Industry: ${base.industry}
Company size: ${base.company_size}
Monthly revenue: ${base.monthly_revenue}
Country: ${base.country}

Tools currently used:
${base.tools_currently_use}

How operation runs today:
${base.operation_today}

Biggest pains:
${base.biggest_pain}

Estimated hours lost per week:
${base.hours_lost_per_week}

Team AI experience:
${base.team_ai_experience}

Existing automations:
${base.existing_automations}

Data readiness:
${base.data_readiness}

Workflows they want AI to handle:
${base.workflows_ai_handle}

Desired outcomes:
${base.desired_outcomes}

Timeline:
${base.timeline}

Budget:
${base.budget}

Decision authority:
${base.decision_authority}

Constraints / integrations / security:
${base.anything_else}

How they heard about us:
${base.heard_about_us}

Uploaded links:
${base.file_uploads}

Score this lead from 0 to 100.

Scoring logic:
1. Business pain severity: 25
2. Automation fit: 20
3. Budget fit: 15
4. Timeline urgency: 10
5. Decision authority: 10
6. Data readiness and tools: 10
7. Revenue/company size fit: 10

Categories:
- Hot = 80 to 100
- Warm = 60 to 80
- Cold = below 60

Recommended offers:
- Priority Discovery Call + ROI Audit
- Starter Automation Demo
- Lead Qualification + CRM Follow-up System
- Reporting Dashboard + Owner Summary
- Document Processing + Approval Workflow
- AI Customer Support Triage + Reply Drafting
- Free Audit / Nurture
- Not a Fit Right Now

Return only valid JSON matching the structured output parser.
Do not use markdown.
Do not include text outside JSON.
`;

return {
  json: {
    ...base,
    ai_prompt: prompt
  }
};

function get(row, keys) {
  for (const key of keys) {
    if (row[key] !== undefined && row[key] !== null && String(row[key]).trim() !== '') {
      return row[key];
    }
  }
  return '';
}

function normalizeWhatsApp(input) {
  if (!input) return '';

  let v = String(input).replace(/[^0-9+]/g, '');

  if (v.startsWith('+')) return v;
  if (v.length === 10) return '+91' + v;
  if (v.startsWith('91') && v.length === 12) return '+' + v;

  return v;
}

function isYes(input) {
  return ['yes', 'true', '1', 'y'].includes(String(input || '').toLowerCase().trim());
}

function normalizeBoolText(value) {
  return String(value ?? '').trim().toLowerCase();
}

const output = [];
const seenEmails = new Set();

for (const item of $input.all()) {
  const row = item.json;

  const status = normalizeBoolText(get(row, ['status', 'Status']));
  const processed = normalizeBoolText(get(row, ['processed', 'Processed']));

  // Skip rows already processed or already scored/routed
  const alreadyDone =
    processed === 'true' ||
    processed === 'yes' ||
    processed === '1' ||
    [
      'ai scored',
      'scored',
      'discovery scheduled',
      'manual review',
      'nurture',
      'proposal sent',
      'not fit',
      'closed',
      'won',
      'lost'
    ].includes(status);

  if (alreadyDone) continue;

  const fullName = get(row, ['full_name', 'Full name', 'Full Name']);
  const workEmail = get(row, [
    'work_email',
    'Work email',
    'Email address',
    'Email Address',
    'Email'
  ]);
  const rawWhatsapp = get(row, ['contact_no', 'Contact No', 'phone', 'Phone']);
  const companyName = get(row, ['company_name', 'Company name', 'Company Name']);

  const consent = get(row, [
    'I agree that AKcelerateHQ may contact me regarding my automation audit request.',
    'consent',
    'Consent'
  ]);

  if (!fullName || !workEmail || !companyName) continue;

  if (consent && !isYes(consent)) continue;

  // Duplicate protection inside the same run
  const emailKey = String(workEmail).trim().toLowerCase();
  if (seenEmails.has(emailKey)) continue;
  seenEmails.add(emailKey);

  output.push({
    json: {
      row_number: get(row, ['row_number', 'Row Number', 'rowNumber']),
      timestamp: get(row, ['timestamp', 'Timestamp']),
      email_address: get(row, ['Email address', 'Email Address', 'email_address']),
      full_name: fullName,
      work_email: workEmail,
      contact_no: normalizeWhatsApp(rawWhatsapp),
      role_in_business: get(row, ['Your Role in Business', 'role_in_business']),
      company_name: companyName,
      website: get(row, ['Website(Optional)', 'Website', 'website']),
      industry: get(row, ['Industry', 'industry']),
      company_size: get(row, ['Company size', 'company_size']),
      monthly_revenue: get(row, ['Monthly revenue', 'monthly_revenue']),
      country: get(row, ['Country', 'country']),
      tools_currently_use: get(row, ['Tools you currently use', 'tools_currently_use']),
      operation_today: get(row, [
        'How does your operation run today? (Describe your team, processes, and handoffs..)',
        'operation_today'
      ]),
      biggest_pain: get(row, [
        'Where is the biggest pain? (pick all that apply)',
        'biggest_pain'
      ]),
      hours_lost_per_week: get(row, [
        'Estimated hours lost per week to manual work',
        'hours_lost_per_week'
      ]),
      team_ai_experience: get(row, [
